      "week": 7,
      "unit": "Unit 2 · Geography, Regions, Resources, and State Landscapes",
      "title": "Human-Environment Interaction, Hazards, and Conservation",
      "essentialQuestion": "How do communities adapt to environments, manage hazards, and debate resource use?",
